package de.meiapps.meicraft;

import android.app.AlertDialog;
import android.widget.*;
import java.util.*;

/** Named, previewable mechanisms. A draft is retained until its online commit is acknowledged. */
final class MechanicsController {
    final MainActivity activity;volatile int stage;volatile World editing;Mechanics.Block button;
    final List<Mechanics.Block> blocks=new ArrayList<>();volatile boolean saving;String draftName="";boolean draftPressure;Mechanics.Link controlTarget;long draftVersion;
    World platesWorld;long nextPlateScan;final Map<Integer,Long> plateRetry=new HashMap<>();final Map<Integer,Long> plateSignature=new java.util.concurrent.ConcurrentHashMap<>();
    volatile List<int[]> highlights=Collections.emptyList();volatile long highlightUntil;
    MechanicsController(MainActivity activity){this.activity=activity;}
    synchronized void cancel(){draftVersion++;stage=0;saving=false;editing=null;button=null;controlTarget=null;draftPressure=false;blocks.clear();highlights=Collections.emptyList();highlightUntil=0;}
    String hint(){return (draftName.isEmpty()?"":draftName+" · ")+(saving?"Wird gespeichert …":stage==3?"Weiteren Schalter anvisieren und + antippen":stage==1?"Schalter anvisieren und + antippen":stage==2?"Blöcke mit + markieren · ⚙ zum Fertigstellen":"");}
    synchronized boolean capture(World w,int[] hit){
        if(stage==0)return false;if(editing!=w){cancel();return true;}if(saving){activity.game.message("Einrichtung wird gespeichert …");return true;}
        if(hit==null){activity.game.message("Näher an einen Block herangehen");return true;}
        try{Mechanics.Block b=new Mechanics.Block(hit[0],hit[1],hit[2],w.get(hit[0],hit[1],hit[2]));Mechanics.valid(b);
            if(stage==3){addCaptured(w,b);return true;}
            if(stage==1){if(w.mechanics.at(w,b.x,b.y,b.z)!=null)throw new IllegalArgumentException("Hier gibt es bereits einen Schalter. Bitte in der Verwaltung auswählen.");button=b;stage=2;}
            else{if(b.key().equals(button.key()))throw new IllegalArgumentException("Der Schalter bleibt stehen");int found=-1;for(int i=0;i<blocks.size();i++)if(blocks.get(i).key().equals(b.key()))found=i;if(found>=0)blocks.remove(found);else{if(blocks.size()==Mechanics.MAX_BLOCKS)throw new IllegalArgumentException("Höchstens neun Blöcke");blocks.add(b);}}
            List<int[]> marks=new ArrayList<>();marks.add(new int[]{button.x,button.y,button.z});for(Mechanics.Block c:blocks)marks.add(new int[]{c.x,c.y,c.z});highlights=marks;highlightUntil=Long.MAX_VALUE;activity.game.message(blocks.size()+" / 9 Blöcke · ⚙ zum Fertigstellen");
        }catch(IllegalArgumentException e){activity.game.message(e.getMessage());}return true;
    }
    void open(){World w=activity.world;if(w==null)return;if(saving){activity.game.message("Einrichtung wird gespeichert …");return;}activity.paused=true;activity.game.clearInput();
        if(stage==2&&editing==w){direction();return;}
        new AlertDialog.Builder(activity).setTitle("Mechanik").setMessage("Schalter und bewegliche Blöcke auswählen. Erst nach bestätigtem Speichern ist die Verbindung fertig. Auslöser: Antippen oder Draufstehen. Weitere Schalter lassen sich anschließend in der Verwaltung verbinden.")
            .setPositiveButton("Neue Mechanik",(d,n)->activity.handler.post(()->nameDraft(w)))
            .setNeutralButton("Verwalten / Anzeigen",(d,n)->activity.handler.post(this::removeMenu))
            .setNegativeButton(stage>0?"Auswahl abbrechen":"Zurück",(d,n)->cancel()).setOnDismissListener(d->activity.resumePlay()).show();
    }
    EditText nameInput(String value){EditText input=new EditText(activity);input.setSingleLine();input.setText(value);input.setHint("z. B. Geheimtür");input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(16)});return input;}
    void nameDraft(World w){activity.paused=true;EditText input=nameInput("Mechanik");AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("Mechanik benennen").setView(input).setPositiveButton("Blöcke auswählen",null).setNegativeButton("Abbrechen",null).setOnDismissListener(d->activity.resumePlay()).create();dialog.show();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view->{try{String name=Mechanics.validName(input.getText().toString());synchronized(this){cancel();editing=w;draftName=name;stage=1;}dialog.dismiss();activity.handler.post(this::draftTrigger);}catch(IllegalArgumentException e){input.setError(e.getMessage());}});}
    void draftTrigger(){activity.paused=true;new AlertDialog.Builder(activity).setTitle("Wie wird ausgelöst?").setItems(new String[]{"Antippen · Schalter anvisieren und ⚙","Draufstehen · offen, solange jemand auf einer Platte steht"},(d,n)->{draftPressure=n==1;activity.game.message(hint());}).setOnCancelListener(d->cancel()).setOnDismissListener(d->activity.resumePlay()).show();}
    void direction(){if(blocks.isEmpty()){activity.toast("Erst mindestens einen Block mit + markieren");activity.resumePlay();return;}activity.paused=true;
        new AlertDialog.Builder(activity).setTitle("In welche Richtung?").setItems(Mechanics.LABELS,(d,n)->activity.handler.post(()->distance(n))).setNegativeButton("Weiter markieren",null).setNeutralButton("Abbrechen",(d,n)->cancel()).setOnDismissListener(d->activity.resumePlay()).show();}
    void distance(int direction){activity.paused=true;new AlertDialog.Builder(activity).setTitle("Wie weit?").setItems(new String[]{"1 Block","2 Blöcke","3 Blöcke","4 Blöcke"},(d,n)->activity.handler.post(()->review(direction,n+1))).setNegativeButton("Zurück",(d,n)->activity.handler.post(this::direction)).setOnDismissListener(d->activity.resumePlay()).show();}
    void review(int direction,int distance){if(editing==null||button==null)return;activity.paused=true;new AlertDialog.Builder(activity).setTitle(draftName.isEmpty()?"Mechanik speichern":draftName)
        .setMessage((draftPressure?"Druckplatte · Rückweg automatisch":"Schalter · Antippen")+"\n"+blocks.size()+" bewegliche Blöcke\n"+Mechanics.LABELS[direction]+" · "+distance+" Block/Blöcke\nSchalter: "+button.x+" / "+button.y+" / "+button.z+"\n\nDer Weg wird beim Schalten geprüft. Deine Auswahl bleibt bei einem Speicherfehler erhalten.")
        .setPositiveButton("Speichern",(d,n)->save(direction,distance)).setNegativeButton("Weiter markieren",null).setOnDismissListener(d->activity.resumePlay()).show();}
    synchronized void save(int direction,int distance){
        if(saving||editing==null||button==null||blocks.isEmpty())return;World w=editing;Mechanics.Block selected=button;List<Mechanics.Block> group=new ArrayList<>(blocks);String name=draftName;long ticket=draftVersion;saving=true;activity.game.clearInput();
        activity.game.gl.queueEvent(()->{try{Mechanics.Link link=new Mechanics.Link(selected,group,direction,distance,false,name,draftPressure,List.of(selected));
            if(w!=activity.game.world){activity.runOnUiThread(()->completed(w,ticket,new IllegalArgumentException("Welt gewechselt")));return;}
            if(w.online)online().configure(link,error->completed(w,ticket,error));
            else{synchronized(w){w.mechanics.install(w,link);}activity.runOnUiThread(()->completed(w,ticket,null));}
        }catch(Exception e){activity.runOnUiThread(()->completed(w,ticket,e));}});
    }
    synchronized void completed(World w,long ticket,Exception error){
        if(editing!=w||ticket!=draftVersion)return;saving=false;if(error==null){cancel();activity.game.message("Mechanik bereit · ⚙ antippen oder Druckplatte betreten");return;}
        activity.paused=true;new AlertDialog.Builder(activity).setTitle("Einrichtung nicht gespeichert").setMessage((error.getMessage()==null?"Bitte erneut versuchen.":error.getMessage())+"\n\nDie markierten Blöcke bleiben ausgewählt.")
            .setPositiveButton("Auswahl behalten",null).setNegativeButton("Auswahl abbrechen",(d,n)->cancel()).setOnDismissListener(d->activity.resumePlay()).show();
    }
    OnlineMechanics online(){OnlineSession s=activity.online==null?null:activity.online.session;if(s==null||!(s.modern instanceof OnlineV6))throw new IllegalArgumentException("Mechanik braucht die aktuelle Online-Version");return ((OnlineV6)s.modern).mechanisms;}
    void use(){if(stage!=0){open();return;}activity.game.gl.queueEvent(()->{World w=activity.game.world;if(w==null)return;Mechanics.Link link;synchronized(w){int[] hit=w.ray(6);link=hit==null?null:w.mechanics.at(w,hit[0],hit[1],hit[2]);}if(link==null){activity.runOnUiThread(this::open);return;}activate(w,link);});}
    void activate(World w,Mechanics.Link link){try{if(w!=activity.game.world)return;if(w.online)online().toggle(link);else{synchronized(w){List<Mechanics.Block> changed=Mechanics.plan(link,Mechanics.space(w));w.mechanics.apply(w,link);for(Mechanics.Block b:changed)activity.game.renderer.dirty(b.x,b.z);}activity.game.message(link.moved?"Zurückgeschoben":"Verschoben");}}catch(Exception e){activity.game.message(e.getMessage());}}
    String title(Mechanics.Link link){return link.name.isEmpty()?World.NAMES[link.button.type]+"-Schalter "+link.button.x+" / "+link.button.y+" / "+link.button.z:link.name;}
    double distance(World w,Mechanics.Link link){double dx=link.button.x+.5-w.x,dy=link.button.y+.5-w.y,dz=link.button.z+.5-w.z;return Math.sqrt(dx*dx+dy*dy+dz*dz);}
    void focus(World w,Mechanics.Link link){activity.game.gl.queueEvent(()->{if(activity.game.world!=w)return;synchronized(w){double dx=link.button.x+.5-w.x,dy=link.button.y+.5-w.y,dz=link.button.z+.5-w.z;w.yaw=(float)Math.atan2(-dx,-dz);w.pitch=(float)Math.max(-1.48,Math.min(1.48,Math.atan2(dy,Math.sqrt(dx*dx+dz*dz))));List<int[]> marks=new ArrayList<>();for(Mechanics.Block button:link.buttons)marks.add(new int[]{button.x,button.y,button.z});int[] d=Mechanics.DIRECTIONS[link.direction];for(Mechanics.Block b:link.blocks)marks.add(new int[]{b.x+(link.moved?d[0]*link.distance:0),b.y+(link.moved?d[1]*link.distance:0),b.z+(link.moved?d[2]*link.distance:0)});highlights=marks;highlightUntil=System.currentTimeMillis()+15000;activity.game.message(title(link)+" · Schalter markiert (15 s)");}});}
    void removeMenu(){World w=activity.world;if(w==null)return;List<Mechanics.Link> list;synchronized(w){list=new ArrayList<>(w.mechanics.links.values());list.sort(Comparator.comparingDouble(link->distance(w,link)));}String[] labels=new String[list.size()];for(int i=0;i<labels.length;i++){Mechanics.Link link=list.get(i);labels[i]=title(link)+"\n"+link.blocks.size()+" Blöcke · "+link.buttons.size()+" "+(link.pressure?"Druckplatten":"Schalter")+" · "+Math.round(distance(w,link))+" m · "+(link.moved?"verschoben":"Grundstellung")+"\nSchalter "+link.button.x+" / "+link.button.y+" / "+link.button.z;}
        activity.paused=true;AlertDialog.Builder dialog=new AlertDialog.Builder(activity).setTitle("Mechaniken · nächste zuerst").setNegativeButton("Zurück",null).setOnDismissListener(d->activity.resumePlay());if(list.isEmpty())dialog.setMessage("Hier sind noch keine Schalter eingerichtet.");else dialog.setItems(labels,(d,n)->activity.handler.post(()->details(w,list.get(n))));dialog.show();}
    void details(World w,Mechanics.Link link){if(activity.world!=w)return;activity.paused=true;new AlertDialog.Builder(activity).setTitle(title(link)).setItems(new String[]{"In der Welt markieren","Schalten","Umbenennen","Weiteren Schalter hinzufügen",link.pressure?"Auslöser ändern · jetzt Draufstehen":"Auslöser ändern · jetzt Antippen","Zusätzliche Schalter entfernen","Verbindung entfernen"},(d,n)->{if(n==0)focus(w,link);else if(n==1)activity.game.gl.queueEvent(()->activate(w,link));else if(n==2)activity.handler.post(()->rename(w,link));else if(n==3)activity.handler.post(()->addControl(w,link));else if(n==4)activity.handler.post(()->chooseTrigger(w,link));else if(n==5)activity.handler.post(()->clearControls(w,link));else activity.handler.post(()->confirmRemove(w,link));}).setNegativeButton("Zurück",(d,n)->activity.handler.post(this::removeMenu)).setOnDismissListener(d->activity.resumePlay()).show();}
    void rename(World w,Mechanics.Link link){activity.paused=true;EditText input=nameInput(link.name);AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("Mechanik umbenennen").setView(input).setPositiveButton("Speichern",null).setNegativeButton("Abbrechen",null).setOnDismissListener(d->activity.resumePlay()).create();dialog.show();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view->{try{if(activity.world!=w)throw new IllegalArgumentException("Welt gewechselt");String name=Mechanics.validName(input.getText().toString());Mechanics.Link named=link.named(name);if(w.online){dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);online().rename(link,named,error->{if(error==null)dialog.dismiss();else{input.setError(error.getMessage());dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);}});}else{synchronized(w){Mechanics.Link current=w.mechanics.links.get(w.idx(link.button.x,link.button.y,link.button.z));if(current==null||!current.encode().equals(link.encode()))throw new IllegalArgumentException("Schalter inzwischen geändert");w.mechanics.links.put(w.idx(link.button.x,link.button.y,link.button.z),named);}dialog.dismiss();}}catch(Exception e){input.setError(e.getMessage());}});}
    void chooseTrigger(World w,Mechanics.Link link){activity.paused=true;new AlertDialog.Builder(activity).setTitle("Auslöser").setSingleChoiceItems(new String[]{"Antippen","Draufstehen · automatisch zurück"},link.pressure?1:0,(d,n)->{d.dismiss();storeControls(w,link,link.mode(n==1));}).setNegativeButton("Zurück",null).setOnDismissListener(d->activity.resumePlay()).show();}
    void addControl(World w,Mechanics.Link link){if(link.buttons.size()>=Mechanics.MAX_BUTTONS){activity.toast("Höchstens drei Schalter pro Mechanik");return;}synchronized(this){cancel();editing=w;controlTarget=link;stage=3;draftName=title(link);}activity.game.message(hint());}
    synchronized void addCaptured(World w,Mechanics.Block button){Mechanics.Link link=controlTarget;if(link==null)return;if(w.mechanics.at(w,button.x,button.y,button.z)!=null)throw new IllegalArgumentException("Hier ist bereits ein Schalter");List<Mechanics.Block> buttons=new ArrayList<>(link.buttons);buttons.add(button);Mechanics.Link next=link.withButtons(buttons);saving=true;storeControls(w,link,next);}
    void clearControls(World w,Mechanics.Link link){activity.paused=true;new AlertDialog.Builder(activity).setTitle("Zusätzliche Schalter entfernen?").setMessage("Der erste Schalter bleibt verbunden. Die anderen Blöcke bleiben stehen.").setPositiveButton("Entfernen",(d,n)->storeControls(w,link,link.withButtons(List.of(link.button)))).setNegativeButton("Zurück",null).setOnDismissListener(d->activity.resumePlay()).show();}
    void storeControls(World w,Mechanics.Link expected,Mechanics.Link next){activity.game.gl.queueEvent(()->{try{if(activity.game.world!=w)return;
        if(w.online)online().rename(expected,next,error->{saving=false;if(error==null){if(stage==3)cancel();activity.game.message("Auslöser gespeichert");}else activity.game.message(error.getMessage());});
        else{synchronized(w){Mechanics.Link current=w.mechanics.links.get(w.idx(expected.button.x,expected.button.y,expected.button.z));if(current==null||!current.encode().equals(expected.encode()))throw new IllegalArgumentException("Schalter inzwischen geändert");for(Mechanics.Block b:next.buttons)if(w.get(b.x,b.y,b.z)!=b.type)throw new IllegalArgumentException("Schalter verändert");w.mechanics.links.put(w.idx(next.button.x,next.button.y,next.button.z),next);w.revision++;}saving=false;if(stage==3)cancel();activity.game.message("Auslöser gespeichert");}
        }catch(Exception e){saving=false;activity.game.message(e.getMessage());}});}
    void tick(World w,float dt){if(platesWorld!=w){platesWorld=w;plateRetry.clear();plateSignature.clear();nextPlateScan=0;}long now=System.nanoTime();if(now<nextPlateScan)return;nextPlateScan=now+250000000L;
        for(Mechanics.Link link:new ArrayList<>(w.mechanics.links.values())){if(!link.pressure)continue;int key=w.idx(link.button.x,link.button.y,link.button.z);if(now<plateRetry.getOrDefault(key,0L))continue;boolean pressed=!w.online&&Mechanics.pressed(link,Mechanics.space(w),w.x,w.y,w.z);
            if(w.online){OnlineSession session=activity.online==null?null:activity.online.session;if(session==null||!session.foreground||session.loading||!(session.modern instanceof OnlineV6))continue;
                long serverNow=System.currentTimeMillis()+((OnlineV6)session.modern).db.serverOffset;long signature=31L*w.revision+link.encode().hashCode();
                for(OnlineSession.Player player:session.players)if(serverNow-player.serverTime<10000){long age=serverNow-player.serverTime;signature+=(age<8000?11:23)+31L*player.uid.hashCode()+17L*player.sector+Float.floatToIntBits(player.x)+3L*Float.floatToIntBits(player.y)+7L*Float.floatToIntBits(player.z);if(age<8000&&Mechanics.pressed(link,Mechanics.space(w),player.x+player.sector%session.side*World.W,player.y,player.z+player.sector/session.side*World.D))pressed=true;}
                if(pressed!=link.moved){long stamp=signature;if(plateSignature.getOrDefault(key,Long.MIN_VALUE)==stamp)continue;plateRetry.put(key,now+1000000000L);plateSignature.put(key,stamp);if(!online().pressure(link,()->plateSignature.remove(key,stamp)))plateSignature.remove(key,stamp);}
            }else if(pressed!=link.moved){plateRetry.put(key,now+750000000L);try{List<Mechanics.Block> changed=Mechanics.plan(link,Mechanics.space(w));w.mechanics.apply(w,link);for(Mechanics.Block b:changed)activity.game.renderer.dirty(b.x,b.z);}catch(IllegalArgumentException ignored){/* A blocked return waits until the entire path is free. */}}
        }
    }
    void confirmRemove(World w,Mechanics.Link link){activity.paused=true;new AlertDialog.Builder(activity).setTitle(title(link)+" entfernen?").setMessage("Schalter "+link.button.x+" / "+link.button.y+" / "+link.button.z+"\nNur die Verbindung wird entfernt. Alle Blöcke bleiben stehen.").setPositiveButton("Entfernen",(d,n)->activity.game.gl.queueEvent(()->{try{if(activity.game.world!=w)return;if(w.online)online().remove(link,error->{if(error!=null)activity.toast("Nicht entfernt: "+error.getMessage());});else{synchronized(w){w.mechanics.links.remove(w.idx(link.button.x,link.button.y,link.button.z));}activity.game.message("Verbindung entfernt");}}catch(Exception e){activity.game.message(e.getMessage());}})).setNegativeButton("Abbrechen",null).setOnDismissListener(d->activity.resumePlay()).show();}
}
